const assert = require('node:assert/strict');

        const { Ledger } = require('../.build/ledger');
        const { PaymentService } = require('../.build/service');
        const { Transient } = require('../.build/transport');
        async function main() {
          const ledger = new Ledger(); const receipts = [];
          const service = new PaymentService(ledger, { acknowledge: async r => { receipts.push(r); } });
          assert.deepEqual(await service.pay('shop', 'sale', 123), { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
          assert.equal(ledger.entries.length, 1); assert.equal(receipts.length, 1);
          await assert.rejects(service.pay('shop', 'bad', 0), /invalid payment/);

          // Repeated equal amount returns original receipt without a second debit, including concurrently.
          const l2 = new Ledger(); let acks = 0;
          const s2 = new PaymentService(l2, { acknowledge: async () => { acks++; } });
          const rs = await Promise.all([s2.pay('t', 'k', 5), s2.pay('t', 'k', 5), s2.pay('t', 'k', 5)]);
          assert.equal(l2.entries.length, 1); assert.deepEqual(rs[0], rs[1]); assert.deepEqual(rs[1], rs[2]);
          assert.equal(acks, 3);
          // Key conflict: different amount, no debit.
          await assert.rejects(s2.pay('t', 'k', 6), { message: 'key conflict' });
          assert.equal(l2.entries.length, 1);
          // Tenant scoping: same key under another tenant is a new debit.
          assert.equal((await s2.pay('u', 'k', 6)).id, 2);
          // Ledger-level key collision must not happen via delimiters.
          assert.equal((await l2.apply('a', 'b:c', 1)).id, 3);
          assert.equal((await l2.apply('a:b', 'c', 1)).id, 4);

          // Transient ack retries reuse the same receipt, debit once.
          const l3 = new Ledger(); let seen = [], calls = 0;
          const s3 = new PaymentService(l3, { acknowledge: async r => { seen.push(r); if (++calls < 3) throw new Transient('x'); } });
          const r3 = await s3.pay('t', 'k', 7, 3);
          assert.equal(l3.entries.length, 1); assert.equal(seen.length, 3);
          assert.ok(seen.every(r => r === seen[0])); assert.deepEqual(r3, seen[0]);

          // Exhausted retries throw the final Transient, after exactly `attempts` tries.
          const l4 = new Ledger(); let n4 = 0; const last = new Transient('last');
          const s4 = new PaymentService(l4, { acknowledge: async () => { n4++; throw n4 < 5 ? new Transient('e' + n4) : last; } });
          await assert.rejects(s4.pay('t', 'k', 1, 5), e => e === last);
          assert.equal(n4, 5); assert.equal(l4.entries.length, 1);

          // Non-Transient errors are not retried.
          const l5 = new Ledger(); let n5 = 0; const boom = new Error('boom');
          const s5 = new PaymentService(l5, { acknowledge: async () => { n5++; throw boom; } });
          await assert.rejects(s5.pay('t', 'k', 1, 5), e => e === boom);
          assert.equal(n5, 1);

          // Transient from apply itself is retried without double debit.
          let applyCalls = 0; const real = new Ledger();
          const flaky = { apply: async (...a) => { if (++applyCalls === 1) throw new Transient('a'); return real.apply(...a); } };
          const s6 = new PaymentService(flaky, { acknowledge: async () => {} });
          assert.equal((await s6.pay('t', 'k', 9, 2)).id, 1); assert.equal(real.entries.length, 1);

          // Invalid input: no ledger or transport action.
          let touched = 0;
          const spy = { apply: async () => { touched++; return {}; } };
          const s7 = new PaymentService(spy, { acknowledge: async () => { touched++; } });
          const bad = [['', 'k', 1], ['t', '', 1], [' ', undefined, 1], [null, 'k', 1], ['t', 'k', 0], ['t', 'k', 1.5], ['t', 'k', -1], ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 1.5], ['t', 'k', 1, '2']];
          for (const args of bad) await assert.rejects(s7.pay(...args), /^Error: invalid payment$/);
          assert.equal(touched, 0);
        }
        module.exports = main();
EOF
